def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        base = DAILY_SALARY * 0.35
        if hp <= 3 or no_water_days >= 1:
            base = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= budget:
            rich_opp += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid', 0.0)))
            except Exception:
                pass

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    survival_pressure = 0.0
    if hp <= 2:
        survival_pressure += 0.55
    elif hp <= 4:
        survival_pressure += 0.3
    if no_water_days >= 2:
        survival_pressure += 0.35
    elif no_water_days >= 1:
        survival_pressure += 0.18

    market_pressure = 0.0
    if highest_prev >= DAILY_SALARY * 2.0:
        market_pressure = 0.55
    elif highest_prev >= DAILY_SALARY * 1.2:
        market_pressure = 0.4
    elif highest_prev >= DAILY_SALARY * 0.8:
        market_pressure = 0.25
    elif highest_prev > 0:
        market_pressure = 0.12

    opp_pressure = 0.04 * urgent_opp + 0.03 * rich_opp

    score = 0.18 + 0.32 * scarcity + survival_pressure + market_pressure + opp_pressure

    if day >= 8:
        score += 0.08
    if day >= 9 and hp <= 5:
        score += 0.12

    if highest_prev >= 120 and hp >= 6 and no_water_days == 0 and supply >= 20:
        score -= 0.18

    if avg_prev < 20 and hp >= 6 and no_water_days == 0:
        score -= 0.08

    if score < 0.08:
        score = 0.08
    if score > 1.45:
        score = 1.45

    bid = DAILY_SALARY * score

    if highest_prev > 0:
        if hp <= 4 or no_water_days >= 1 or supply <= 17:
            target = highest_prev + 2.0
            if bid < target:
                bid = target
        elif highest_prev >= 120 and supply >= 21:
            bid = min(bid, highest_prev * 0.72)
        else:
            soft_target = highest_prev + 1.0
            if soft_target < DAILY_SALARY * 1.15:
                bid = max(bid, soft_target)

    reserve = 0.0
    if hp <= 3:
        reserve = DAILY_SALARY * 0.2
    elif no_water_days >= 1:
        reserve = DAILY_SALARY * 0.1

    max_affordable = max(0.0, budget - reserve)
    if hp <= 2 or no_water_days >= 2:
        max_affordable = budget

    if bid > max_affordable:
        bid = max_affordable

    if bid < 0:
        bid = 0.0

    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids to infer aggressiveness.
    yesterday_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Supply pressure: if supply is tight relative to our requirement, we need water.
    # Determine how many full water quanta could exist.
    # Use int() indices only; here we avoid indexing.
    full_quanta = int(supply / float(WATER_REQ)) if WATER_REQ > 0 else 0

    # Base bid: aim to be competitive but not always match the top spender.
    # If supply is low (<= 2 quanta), bid higher to secure.
    if supply <= float(MIN_SUPPLY) + 0.5:
        base = DAILY_SALARY * 0.75
    elif full_quanta <= 1:
        base = DAILY_SALARY * 0.7
    else:
        base = DAILY_SALARY * 0.58

    # Exploit yesterday: when someone bid very high, they likely try to lock water.
    # We counter with a slightly lower but still strong bid to win ties/near-ties.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        base = max(base, DAILY_SALARY * 0.78)

    # If my hp/no-water is critical, bid aggressively to avoid another no-water day.
    if my_hp <= 2 or my_no_water_days >= 2:
        base = max(base, DAILY_SALARY * 0.92)
    elif my_hp <= 4:
        base = max(base, DAILY_SALARY * 0.72)

    # Budget cap and non-negative.
    bid = max(0.0, min(my_budget, base))

    # If supply is high, we can safely bid a bit less.
    if supply >= float(MAX_SUPPLY) - 0.5 and my_hp >= 7 and my_no_water_days == 0:
        bid = max(0.0, min(my_budget, DAILY_SALARY * 0.5))

    # Ensure bid is within reasonable range.
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    max_prev = max(yesterday_bids) if yesterday_bids else 80

    if my_status['hp'] <= 3:
        return min(my_status['budget'], max_prev * 1.1)

    if supply < 18:
        return min(my_status['budget'], max(80, max_prev * 1.05))

    return min(my_status['budget'], max(50, max_prev * 0.8))
